#[cfg(debug_assertions)]
fn _bostree_print_helper(node: &Rc<RefCell<BOSNode>>) {
    let nb = node.borrow();
    println!(
        "  {} [label=\"\\N ({},{},{})\"];",
        nb.key, nb.left_child_count, nb.right_child_count, nb.depth
    );
    if let Some(ref pw) = nb.parent_node {
        if let Some(parent) = pw.upgrade() {
            println!("  {} -> {} [color=green];", nb.key, parent.borrow().key);
        }
    }
    if let Some(ref left) = nb.left_child_node {
        println!("  {} -> {}", nb.key, left.borrow().key);
        drop(nb);
        _bostree_print_helper(left);
        // Re-borrow not needed since we're done with this node
    }
    // Need to re-borrow for right child since we dropped above
    let nb2 = node.borrow();
    if let Some(ref right) = nb2.right_child_node {
        println!("  {} -> {}", nb2.key, right.borrow().key);
        drop(nb2);
        _bostree_print_helper(right);
    }
}

/// Increase the weak reference count for a node and return the node.
pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let mut nb = node.borrow_mut();
    assert!(nb.weak_ref_count < 127);
    assert!(nb.weak_ref_count > 0);
    nb.weak_ref_count += 1;
    node.clone()
}

