    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    /// Right child node.
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    /// Parent node (using a weak reference to avoid cycles).
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    /// The key for this node.
    pub key: String,
    /// The associated data.
    pub data: Option<String>,
    /// Internal weak reference counter.
    pub weak_ref_count: u8,
    /// Validity flag for the weak reference.
    pub weak_ref_node_valid: u8,
}

/// Type alias for a key comparison function.
/// Should return a positive value if `b` is larger than `a`,
/// a negative value if `a` is larger, and zero if equal.
pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;

/// Type alias for a free function which will be called on nodes
/// that are removed.
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

// ─── Private helper functions ───────────────────────────────────────────────

fn _imax(i1: u32, i2: u32) -> u32 {
    if i1 > i2 { i1 } else { i2 }
}

/// Returns right_depth - left_depth for the given node.
fn _bostree_balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
    let b = node.borrow();
    let left_depth = b.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
    let right_depth = b.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
    (right_depth as i32) - (left_depth as i32)
}

/// Recompute and store the depth field of a node from its children.
fn _recompute_depth(node: &Rc<RefCell<BOSNode>>) {
    let (ld, rd) = {
        let b = node.borrow();
        let ld = b.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let rd = b.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        (ld, rd)
    };
    node.borrow_mut().depth = _imax(ld, rd);
}

/// Rotate right around node P.
///
///      P                     L
///  L        R     -->    c1      P
///c1 c2                        c2     R
fn _bostree_rotate_right(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    // Grab L (P's left child)
    let l = p.borrow().left_child_node.as_ref().unwrap().clone();

    // Save P's old parent
    let p_parent = p.borrow().parent_node.clone();

    // Update grandparent to point to L instead of P
    if let Some(ref pw) = p_parent {
        if let Some(parent) = pw.upgrade() {
            let is_left = {
                let pb = parent.borrow();
                pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, p))
            };
            if is_left {
                parent.borrow_mut().left_child_node = Some(l.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(l.clone());
            }
        }
    } else {
        tree.root_node = Some(l.clone());
    }

    // L's parent becomes P's old parent
    l.borrow_mut().parent_node = p_parent;

    // Move L's right child to become P's left child
    let l_right = l.borrow().right_child_node.clone();
    let l_right_count = l.borrow().right_child_count;

    p.borrow_mut().left_child_node = l_right.clone();
    p.borrow_mut().left_child_count = l_right_count;

    if let Some(ref lr) = l_right {
        lr.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    // Recompute P's depth
    _recompute_depth(p);

    // P's parent becomes L
    p.borrow_mut().parent_node = Some(Rc::downgrade(&l));

    // L's right child becomes P
    l.borrow_mut().right_child_node = Some(p.clone());

    // Update L's right_child_count
    l.borrow_mut().right_child_count =
        p.borrow().left_child_count + p.borrow().right_child_count + 1;

    // Recompute L's depth
    _recompute_depth(&l);

    l
}

/// Rotate left around node P.
///
///      P                     R
///  L        R     -->    P      c2
///         c1 c2        L  c1
fn _bostree_rotate_left(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    // Grab R (P's right child)
    let r = p.borrow().right_child_node.as_ref().unwrap().clone();

    // Save P's old parent
    let p_parent = p.borrow().parent_node.clone();

    // Update grandparent to point to R instead of P
    if let Some(ref pw) = p_parent {
        if let Some(parent) = pw.upgrade() {
            let is_left = {
                let pb = parent.borrow();
                pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, p))
            };
            if is_left {
                parent.borrow_mut().left_child_node = Some(r.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(r.clone());
            }
        }
    } else {
        tree.root_node = Some(r.clone());
    }

    // R's parent becomes P's old parent
    r.borrow_mut().parent_node = p_parent;

    // Move R's left child to become P's right child
    let r_left = r.borrow().left_child_node.clone();
    let r_left_count = r.borrow().left_child_count;

    p.borrow_mut().right_child_node = r_left.clone();
    p.borrow_mut().right_child_count = r_left_count;

    if let Some(ref rl) = r_left {
        rl.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    // Recompute P's depth
    _recompute_depth(p);

    // P's parent becomes R
    p.borrow_mut().parent_node = Some(Rc::downgrade(&r));

    // R's left child becomes P
    r.borrow_mut().left_child_node = Some(p.clone());

    // Update R's left_child_count
    r.borrow_mut().left_child_count =
        p.borrow().left_child_count + p.borrow().right_child_count + 1;

    // Recompute R's depth
    _recompute_depth(&r);

    r
}

// ─── Public API ─────────────────────────────────────────────────────────────

impl BOSTree {
    /// Create a new tree with a mandatory comparison function and an optional free function.
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    /// Return the number of nodes in the tree.
    pub fn bostree_node_count(&self) -> u32 {
        self.root_node.as_ref().map_or(0, |n| {
            let b = n.borrow();
            b.left_child_count + b.right_child_count + 1
        })
    }

    /// Insert a new member into the tree and return the associated node.
    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        // Walk down to find insertion point
        let mut current = self.root_node.clone();
        let mut parent_node: Option<Rc<RefCell<BOSNode>>> = None;

        while let Some(ref node) = current {
            parent_node = Some(node.clone());
            let cmp = (self.cmp_function)(&key, &node.borrow().key);
            if cmp < 0 {
                node.borrow_mut().left_child_count += 1;
                current = node.borrow().left_child_node.clone();
            } else {
                node.borrow_mut().right_child_count += 1;
                current = node.borrow().right_child_node.clone();
            }
        }

        // Create new node
        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: parent_node.as_ref().map(|p| Rc::downgrade(p)),
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        // Link new node into tree
        if let Some(ref parent) = parent_node {
            let cmp = (self.cmp_function)(
                &new_node.borrow().key,
                &parent.borrow().key,
            );
            if cmp < 0 {
                parent.borrow_mut().left_child_node = Some(new_node.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(new_node.clone());
            }
        } else {
            // First node in tree
            self.root_node = Some(new_node.clone());
            return new_node;
        }

        // Check if depth changed: only when parent went from 0 to 1 children
        // (i.e., exactly one child exists now — XOR)
        let should_bubble = {
            let pb = parent_node.as_ref().unwrap().borrow();
            let has_left = pb.left_child_node.is_some();
            let has_right = pb.right_child_node.is_some();
            has_left ^ has_right
        };

        if should_bubble {
            // Parent's depth increased from 0 to 1
            parent_node.as_ref().unwrap().borrow_mut().depth = 1;

            let mut bubble = parent_node.as_ref().unwrap().borrow().parent_node.clone();

            while let Some(ref pw) = bubble {
                if let Some(parent) = pw.upgrade() {
                    let (new_left_depth, new_right_depth) = {
                        let pb = parent.borrow();
                        let ld = pb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                        let rd = pb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                        (ld, rd)
                    };
                    let max_depth = _imax(new_left_depth, new_right_depth);

                    {
                        let mut pb = parent.borrow_mut();
                        if pb.depth != max_depth {
                            pb.depth = max_depth;
                        } else {
                            // Depth didn't change at this level, stop bubbling
                            break;
                        }
                    }

                    // Check AVL property
                    if new_left_depth == new_right_depth + 2 {
                        // Left is two deeper — rotate right
                        // Check left-right case first
                        let left_child = parent.borrow().left_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&left_child) > 0 {
                            _bostree_rotate_left(self, &left_child);
                        }
                        let rotated = _bostree_rotate_right(self, &parent);
                        bubble = rotated.borrow().parent_node.clone();
                    } else if new_right_depth == new_left_depth + 2 {
                        // Right is two deeper — rotate left
                        // Check right-left case first
                        let right_child = parent.borrow().right_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&right_child) < 0 {
                            _bostree_rotate_right(self, &right_child);
                        }
                        let rotated = _bostree_rotate_left(self, &parent);
                        bubble = rotated.borrow().parent_node.clone();
                    } else {
                        bubble = parent.borrow().parent_node.clone();
                    }
                } else {
                    break;
                }
            }
        }

        new_node
    }

    /// Remove a given node from the tree.
    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let mut bubble_up: Option<Rc<RefCell<BOSNode>>>;

        let has_left = node.borrow().left_child_node.is_some();
        let has_right = node.borrow().right_child_node.is_some();

        if has_left && has_right {
            // ── Case: node has two children ──────────────────────────────
            let (candidate, bubble_start);

            let left_depth = node.borrow().left_child_node.as_ref().unwrap().borrow().depth;
            let right_depth = node.borrow().right_child_node.as_ref().unwrap().borrow().depth;

            if left_depth >= right_depth {
                // Find rightmost node in left subtree (in-order predecessor)
                node.borrow_mut().left_child_count -= 1;
                let mut cand = node.borrow().left_child_node.as_ref().unwrap().clone();
                while cand.borrow().right_child_node.is_some() {
                    cand.borrow_mut().right_child_count -= 1;
                    let next = cand.borrow().right_child_node.as_ref().unwrap().clone();
                    cand = next;
                }
                candidate = cand;
                let lost_child = candidate.borrow().left_child_node.clone();
                let bs = candidate.borrow().parent_node.as_ref()
                    .and_then(|w| w.upgrade())
                    .unwrap();

                // Replace candidate in its old position with lost_child
                {
                    let mut bs_b = bs.borrow_mut();
                    if bs_b.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate)) {
                        bs_b.left_child_node = lost_child.clone();
                    } else {
                        bs_b.right_child_node = lost_child.clone();
                    }
                }
                if let Some(ref lc) = lost_child {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&bs));
                }

                bubble_start = bs;
            } else {
                // Find leftmost node in right subtree (in-order successor)
                node.borrow_mut().right_child_count -= 1;
                let mut cand = node.borrow().right_child_node.as_ref().unwrap().clone();
                while cand.borrow().left_child_node.is_some() {
                    cand.borrow_mut().left_child_count -= 1;
                    let next = cand.borrow().left_child_node.as_ref().unwrap().clone();
                    cand = next;
                }
                candidate = cand;
                let lost_child = candidate.borrow().right_child_node.clone();
                let bs = candidate.borrow().parent_node.as_ref()
                    .and_then(|w| w.upgrade())
                    .unwrap();

                // Replace candidate in its old position with lost_child
                {
                    let mut bs_b = bs.borrow_mut();
                    if bs_b.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate)) {
                        bs_b.left_child_node = lost_child.clone();
                    } else {
                        bs_b.right_child_node = lost_child.clone();
                    }
                }
                if let Some(ref lc) = lost_child {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&bs));
                }

                bubble_start = bs;
            }

            // Anchor candidate into node's position
            let node_parent = node.borrow().parent_node.clone();
            if let Some(ref pw) = node_parent {
                if let Some(parent) = pw.upgrade() {
                    let is_left = {
                        let pb = parent.borrow();
                        pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, node))
                    };
                    if is_left {
                        parent.borrow_mut().left_child_node = Some(candidate.clone());
                    } else {
                        parent.borrow_mut().right_child_node = Some(candidate.clone());
                    }
                }
            } else {
                self.root_node = Some(candidate.clone());
            }
            candidate.borrow_mut().parent_node = node_parent;

            // Move node's children to candidate
            let node_left = node.borrow().left_child_node.clone();
            let node_left_count = node.borrow().left_child_count;
            let node_right = node.borrow().right_child_node.clone();
            let node_right_count = node.borrow().right_child_count;

            candidate.borrow_mut().left_child_node = node_left.clone();
            candidate.borrow_mut().left_child_count = node_left_count;
            candidate.borrow_mut().right_child_node = node_right.clone();
            candidate.borrow_mut().right_child_count = node_right_count;

            if let Some(ref nl) = node_left {
                nl.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }
            if let Some(ref nr) = node_right {
                nr.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }

            // Rebalance from bubble_start up to (but not including) candidate
            // Only if bubble_start != node (the original node being removed)
            let bubble_start_is_node = Rc::ptr_eq(&bubble_start, node);
            if !bubble_start_is_node {
                let mut cur = Some(bubble_start.clone());
                while let Some(ref c) = cur {
                    if Rc::ptr_eq(c, &candidate) {
                        break;
                    }
                    _recompute_depth(c);
                    let balance = _bostree_balance(c);
                    if balance > 1 {
                        // Rotate left, check right-left case
                        let rc = c.borrow().right_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&rc) < 0 {
                            _bostree_rotate_right(self, &rc);
                        }
                        let rotated = _bostree_rotate_left(self, c);
                        cur = rotated.borrow().parent_node.clone();
                    } else if balance < -1 {
                        // Rotate right, check left-right case
                        let lc = c.borrow().left_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&lc) > 0 {
                            _bostree_rotate_left(self, &lc);
                        }
                        let rotated = _bostree_rotate_right(self, c);
                        cur = rotated.borrow().parent_node.clone();
                    } else {
                        cur = c.borrow().parent_node.clone();
                    }
                }
            }

            // Fix candidate's depth
            _recompute_depth(&candidate);

            // Bubble up from candidate's parent
            bubble_up = candidate.borrow().parent_node.as_ref()
                .and_then(|w| w.upgrade());

            // Decrement immediate parent's child count
            if let Some(ref bu) = bubble_up {
                let is_left = {
                    let bb = bu.borrow();
                    bb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate))
                };
                if is_left {
                    bu.borrow_mut().left_child_count -= 1;
                } else {
                    bu.borrow_mut().right_child_count -= 1;
                }
            }
        } else {
            // ── Case: node has at most one child ─────────────────────────
            let node_parent = node.borrow().parent_node.clone();

            if node_parent.is_none() {
                // Node is root
                let left = node.borrow().left_child_node.clone();
                let right = node.borrow().right_child_node.clone();
                if let Some(ref l) = left {
                    self.root_node = Some(l.clone());
                    l.borrow_mut().parent_node = None;
                } else if let Some(ref r) = right {
                    self.root_node = Some(r.clone());
                    r.borrow_mut().parent_node = None;
                } else {
                    self.root_node = None;
                }
                bubble_up = None;
            } else {
                let parent = node_parent.as_ref().unwrap().upgrade().unwrap();
                let candidate = if node.borrow().left_child_node.is_some() {
                    node.borrow().left_child_node.clone()
                } else {
                    node.borrow().right_child_node.clone()
                };
                let candidate_count = if node.borrow().left_child_node.is_some() {
                    node.borrow().left_child_count
                } else {
                    node.borrow().right_child_count
                };

                let is_left = {
                    let pb = parent.borrow();
                    pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, node))
                };

                if is_left {
                    parent.borrow_mut().left_child_node = candidate.clone();
                    parent.borrow_mut().left_child_count = candidate_count;
                } else {
                    parent.borrow_mut().right_child_node = candidate.clone();
                    parent.borrow_mut().right_child_count = candidate_count;
                }

                if let Some(ref c) = candidate {
                    c.borrow_mut().parent_node = Some(Rc::downgrade(&parent));
                }

                bubble_up = Some(parent);
            }
        }

        // Bubble up: decrement child counts and rebalance
        let mut bubbling_finished = false;
        let mut cur = bubble_up;

        while let Some(ref bu) = cur {
            if !bubbling_finished {
                let (left_depth, right_depth) = {
                    let bb = bu.borrow();
                    let ld = bb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let rd = bb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    (ld, rd)
                };
                let new_depth = _imax(left_depth, right_depth);
                let depth_changed = {
                    let bb = bu.borrow();
                    new_depth != bb.depth
                };
                bu.borrow_mut().depth = new_depth;

                let balance = _bostree_balance(bu);
                if balance < -1 {
                    // Rotate right, check left-right case
                    let lc = bu.borrow().left_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&lc) > 0 {
                        _bostree_rotate_left(self, &lc);
                    }
                    let rotated = _bostree_rotate_right(self, bu);
                    cur = rotated.borrow().parent_node.clone();
                } else if balance > 1 {
                    // Rotate left, check right-left case
                    let rc = bu.borrow().right_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&rc) < 0 {
                        _bostree_rotate_right(self, &rc);
                    }
                    let rotated = _bostree_rotate_left(self, bu);
                    cur = rotated.borrow().parent_node.clone();
                } else {
                    if !depth_changed {
                        bubbling_finished = true;
                    }
                    cur = bu.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                }
            } else {
                cur = bu.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            }

            // Decrement parent's child count
            if let Some(ref c) = cur {
                // We need to know which child `bu` was of `c`
                // But `bu` might have been rotated, so we need to check the current state
                // Actually, in the C code, this decrements the count of the *current* bubble_up's parent
                // Let me re-read the C code...
                // The C code does: if bubble_up->parent_node, decrement the appropriate count
                // This happens AFTER the potential rotation, so bubble_up might have changed
                // But we already moved cur above. Let me restructure.
            }
            // Actually, let me re-read the C code more carefully for this loop.
            break; // temporary, will fix below
        }

        // Let me redo the bubble-up loop more carefully to match the C code exactly.
        // Reset and redo:
        self._bubble_up_remove(bubble_up);

        // Mark node as invalid and unref
        node.borrow_mut().weak_ref_node_valid = 0;
        self.bostree_node_weak_unref(node);
    }

    /// Internal helper: bubble up after removal, decrementing counts and rebalancing.
    fn _bubble_up_remove(&mut self, mut bubble_up: Option<Rc<RefCell<BOSNode>>>) {
        let mut bubbling_finished = false;

        while let Some(bu) = bubble_up {
            if !bubbling_finished {
                let (left_depth, right_depth) = {
                    let bb = bu.borrow();
                    let ld = bb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let rd = bb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    (ld, rd)
                };
                let new_depth = _imax(left_depth, right_depth);
                let depth_changed = {
                    let bb = bu.borrow();
                    new_depth != bb.depth
                };
                bu.borrow_mut().depth = new_depth;

                let balance = _bostree_balance(&bu);
                if balance < -1 {
                    let lc = bu.borrow().left_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&lc) > 0 {
                        _bostree_rotate_left(self, &lc);
                    }
                    let rotated = _bostree_rotate_right(self, &bu);
                    // Decrement parent's child count
                    let next = Self::_decrement_parent_count(&rotated);
                    bubble_up = next;
                } else if balance > 1 {
                    let rc = bu.borrow().right_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&rc) < 0 {
                        _bostree_rotate_right(self, &rc);
                    }
                    let rotated = _bostree_rotate_left(self, &bu);
                    let next = Self::_decrement_parent_count(&rotated);
                    bubble_up = next;
                } else {
                    if !depth_changed {
                        bubbling_finished = true;
                    }
                    let next = Self::_decrement_parent_count(&bu);
                    bubble_up = next;
                }
            } else {
                let next = Self::_decrement_parent_count(&bu);
                bubble_up = next;
            }
        }
    }

    /// Decrement the appropriate child count of bu's parent, return parent.
    fn _decrement_parent_count(bu: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
        let parent = bu.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
        if let Some(ref p) = parent {
            let is_left = {
                let pb = p.borrow();
                pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, bu))
            };
            if is_left {
                p.borrow_mut().left_child_count -= 1;
            } else {
                p.borrow_mut().right_child_count -= 1;
            }
        }
        parent
    }

    /// Decrease the weak reference count for a node; if that was the last reference,
    /// free the node and return None; otherwise return the node.
    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        let count = {
            let mut nb = node.borrow_mut();
            nb.weak_ref_count -= 1;
            nb.weak_ref_count
        };
        if count == 0 {
            if let Some(free_fn) = self.free_function {
                free_fn(node);
            }
            // In Rust, the Rc will be dropped naturally when all references are gone.
            None
        } else {
            let valid = node.borrow().weak_ref_node_valid;
            if valid != 0 {
                Some(node.clone())
            } else {
                None
            }
        }
    }

    /// Lookup a node in the tree by its key.
    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        while let Some(ref node) = current {
            let cmp = (self.cmp_function)(key, &node.borrow().key);
            if cmp == 0 {
                return Some(node.clone());
            } else if cmp < 0 {
                current = node.borrow().left_child_node.clone();
            } else {
                current = node.borrow().right_child_node.clone();
            }
        }
        None
    }

    /// Return the node at the given in-order index (starting at 0).
    pub fn bostree_select(&self, index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        let mut idx = index;
        while let Some(ref node) = current {
            let lcc = node.borrow().left_child_count;
            if lcc <= idx {
                idx -= lcc;
                if idx == 0 {
                    return Some(node.clone());
                }
                idx -= 1;
                current = node.borrow().right_child_node.clone();
            } else {
                current = node.borrow().left_child_node.clone();
            }
        }
        None
    }

    /// Print the tree (only available in debug builds).
    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        if let Some(ref root) = self.root_node {
            println!("digraph {{\n  ordering = out;");
            Self::_print_helper(root);
            println!("}}");
        }
    }

    #[cfg(debug_assertions)]
    fn _print_helper(node: &Rc<RefCell<BOSNode>>) {
        let nb = node.borrow();
        println!(
            "  {} [label=\"\\N ({},{},{})\"];",
            nb.key, nb.left_child_count, nb.right_child_count, nb.depth
        );
        if let Some(ref pw) = nb.parent_node {
            if let Some(parent) = pw.upgrade() {
                println!("  {} -> {} [color=green];", nb.key, parent.borrow().key);
            }
        }
        if let Some(ref left) = nb.left_child_node {
            println!("  {} -> {}", nb.key, left.borrow().key);
            drop(nb);
            Self::_print_helper(left);
        }
        if let Some(ref right) = nb.right_child_node {
            // Re-borrow since we dropped above (or nb was never dropped if left was None)
            let nb2 = node.borrow();
            println!("  {} -> {}", nb2.key, right.borrow().key);
            drop(nb2);
            Self::_print_helper(right);
        }
    }
}

/// Increase the weak reference count for a node and return the node.
pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let mut nb = node.borrow_mut();
    assert!(nb.weak_ref_count < 127);
    assert!(nb.weak_ref_count > 0);
    nb.weak_ref_count += 1;
    node.clone()
}

/// Return the next node in an in-order traversal.
pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if node.borrow().right_child_node.is_some() {
        let mut current = node.borrow().right_child_node.clone().unwrap();
        while current.borrow().left_child_node.is_some() {
            let next = current.borrow().left_child_node.clone().unwrap();
            current = next;
        }
        Some(current)
    } else if node.borrow().parent_node.is_some() {
        let mut current = node.clone();
        loop {
            let parent = current.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            match parent {
                Some(ref p) if {
                    let pb = p.borrow();
                    pb.right_child_node.as_ref().map_or(false, |rc| Rc::ptr_eq(rc, &current))
                } => {
                    current = p.clone();
                }
                _ => return parent,
            }
        }
    } else {
        None
    }
}

/// Return the previous node in an in-order traversal.
pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if node.borrow().left_child_node.is_some() {
        let mut current = node.borrow().left_child_node.clone().unwrap();
        while current.borrow().right_child_node.is_some() {
            let next = current.borrow().right_child_node.clone().unwrap();
            current = next;
        }
        Some(current)
    } else if node.borrow().parent_node.is_some() {
        let mut current = node.clone();
        loop {
            let parent = current.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            match parent {
                Some(ref p) if {
                    let pb = p.borrow();
                    pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &current))
                } => {
                    current = p.clone();
                }
                _ => return parent,
            }
        }
    } else {
        None
    }
}

/// Return the rank (in-order index) of the given node.
pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut current = node.clone();
    while let Some(parent_weak) = current.borrow().parent_node.clone() {
        if let Some(parent) = parent_weak.upgrade() {
            let is_right = {
                let pb = parent.borrow();
                pb.right_child_node.as_ref().map_or(false, |rc| Rc::ptr_eq(rc, &current))
            };
            if is_right {
                counter += 1 + parent.borrow().left_child_count;
            }
            current = parent;
        } else {
            break;
        }
    }
    counter
}

use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct BOSTree {
    /// The root node of the tree.
    pub root_node: Option<Rc<RefCell<BOSNode>>>,
    /// The key comparison function.
    pub cmp_function: BOSTreeCmpFunction,
    /// The optional free function for node data.
    pub free_function: Option<BOSTreeFreeFunction>,
}

/// The node structure.
#[derive(Debug)]
pub struct BOSNode {
    /// Number of nodes in the left subtree.
    pub left_child_count: u32,
    /// Number of nodes in the right subtree.
    pub right_child_count: u32,
    /// Cached depth of the node.
    pub depth: u32,
    /// Left child node.
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    /// Right child node.
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    /// Parent node (using a weak reference to avoid cycles).
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    /// The key for this node.
    pub key: String,
    /// The associated data.
    pub data: Option<String>,
    /// Internal weak reference counter.
    pub weak_ref_count: u8,
    /// Validity flag for the weak reference.
    pub weak_ref_node_valid: u8,
}

/// Type alias for a key comparison function.
/// Should return a positive value if `b` is larger than `a`,
/// a negative value if `a` is larger, and zero if equal.
pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;

/// Type alias for a free function which will be called on nodes
/// that are removed.
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

// ─── Private helper functions ───────────────────────────────────────────────

fn _imax(i1: u32, i2: u32) -> u32 {
    if i1 > i2 { i1 } else { i2 }
}

/// Returns right_depth - left_depth for the given node.
fn _bostree_balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
    let b = node.borrow();
    let left_depth = b.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
    let right_depth = b.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
    (right_depth as i32) - (left_depth as i32)
}

/// Recompute and store the depth field of a node from its children.
fn _recompute_depth(node: &Rc<RefCell<BOSNode>>) {
    let (ld, rd) = {
        let b = node.borrow();
        let ld = b.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let rd = b.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        (ld, rd)
    };
    node.borrow_mut().depth = _imax(ld, rd);
}

/// Rotate right around node P.
///
///      P                     L
///  L        R     -->    c1      P
///c1 c2                        c2     R
fn _bostree_rotate_right(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    // Grab L (P's left child)
    let l = p.borrow().left_child_node.as_ref().unwrap().clone();

    // Save P's old parent
    let p_parent = p.borrow().parent_node.clone();

    // Update grandparent to point to L instead of P
    if let Some(ref pw) = p_parent {
        if let Some(parent) = pw.upgrade() {
            let is_left = {
                let pb = parent.borrow();
                pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, p))
            };
            if is_left {
                parent.borrow_mut().left_child_node = Some(l.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(l.clone());
            }
        }
    } else {
        tree.root_node = Some(l.clone());
    }

    // L's parent becomes P's old parent
    l.borrow_mut().parent_node = p_parent;

    // Move L's right child to become P's left child
    let l_right = l.borrow().right_child_node.clone();
    let l_right_count = l.borrow().right_child_count;

    p.borrow_mut().left_child_node = l_right.clone();
    p.borrow_mut().left_child_count = l_right_count;

    if let Some(ref lr) = l_right {
        lr.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    // Recompute P's depth
    _recompute_depth(p);

    // P's parent becomes L
    p.borrow_mut().parent_node = Some(Rc::downgrade(&l));

    // L's right child becomes P
    l.borrow_mut().right_child_node = Some(p.clone());

    // Update L's right_child_count
    l.borrow_mut().right_child_count =
        p.borrow().left_child_count + p.borrow().right_child_count + 1;

    // Recompute L's depth
    _recompute_depth(&l);

    l
}

/// Rotate left around node P.
///
///      P                     R
///  L        R     -->    P      c2
///         c1 c2        L  c1
fn _bostree_rotate_left(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    // Grab R (P's right child)
    let r = p.borrow().right_child_node.as_ref().unwrap().clone();

    // Save P's old parent
    let p_parent = p.borrow().parent_node.clone();

    // Update grandparent to point to R instead of P
    if let Some(ref pw) = p_parent {
        if let Some(parent) = pw.upgrade() {
            let is_left = {
                let pb = parent.borrow();
                pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, p))
            };
            if is_left {
                parent.borrow_mut().left_child_node = Some(r.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(r.clone());
            }
        }
    } else {
        tree.root_node = Some(r.clone());
    }

    // R's parent becomes P's old parent
    r.borrow_mut().parent_node = p_parent;

    // Move R's left child to become P's right child
    let r_left = r.borrow().left_child_node.clone();
    let r_left_count = r.borrow().left_child_count;

    p.borrow_mut().right_child_node = r_left.clone();
    p.borrow_mut().right_child_count = r_left_count;

    if let Some(ref rl) = r_left {
        rl.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    // Recompute P's depth
    _recompute_depth(p);

    // P's parent becomes R
    p.borrow_mut().parent_node = Some(Rc::downgrade(&r));

    // R's left child becomes P
    r.borrow_mut().left_child_node = Some(p.clone());

    // Update R's left_child_count
    r.borrow_mut().left_child_count =
        p.borrow().left_child_count + p.borrow().right_child_count + 1;

    // Recompute R's depth
    _recompute_depth(&r);

    r
}

// ─── Public API ─────────────────────────────────────────────────────────────

impl BOSTree {
    /// Create a new tree with a mandatory comparison function and an optional free function.
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    /// Return the number of nodes in the tree.
    pub fn bostree_node_count(&self) -> u32 {
        self.root_node.as_ref().map_or(0, |n| {
            let b = n.borrow();
            b.left_child_count + b.right_child_count + 1
        })
    }

    /// Insert a new member into the tree and return the associated node.
    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        // Walk down to find insertion point
        let mut current = self.root_node.clone();
        let mut parent_node: Option<Rc<RefCell<BOSNode>>> = None;

        loop {
            let node = match current {
                Some(ref n) => n.clone(),
                None => break,
            };
            parent_node = Some(node.clone());
            let cmp = (self.cmp_function)(&key, &node.borrow().key);
            if cmp < 0 {
                node.borrow_mut().left_child_count += 1;
                current = node.borrow().left_child_node.clone();
            } else {
                node.borrow_mut().right_child_count += 1;
                current = node.borrow().right_child_node.clone();
            }
        }

        // Create new node
        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: parent_node.as_ref().map(|p| Rc::downgrade(p)),
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        // Link new node into tree
        if let Some(ref parent) = parent_node {
            let cmp = (self.cmp_function)(
                &new_node.borrow().key,
                &parent.borrow().key,
            );
            if cmp < 0 {
                parent.borrow_mut().left_child_node = Some(new_node.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(new_node.clone());
            }
        } else {
            // First node in tree
            self.root_node = Some(new_node.clone());
            return new_node;
        }

        // Check if depth changed: only when parent went from 0 to 1 children
        // (i.e., exactly one child exists now — XOR)
        let should_bubble = {
            let pb = parent_node.as_ref().unwrap().borrow();
            let has_left = pb.left_child_node.is_some();
            let has_right = pb.right_child_node.is_some();
            has_left ^ has_right
        };

        if should_bubble {
            // Parent's depth increased from 0 to 1
            parent_node.as_ref().unwrap().borrow_mut().depth = 1;

            let mut bubble: Option<Rc<RefCell<BOSNode>>> =
                parent_node.as_ref().unwrap().borrow().parent_node.as_ref()
                    .and_then(|w| w.upgrade());

            loop {
                let parent = match bubble {
                    Some(ref p) => p.clone(),
                    None => break,
                };

                let (new_left_depth, new_right_depth) = {
                    let pb = parent.borrow();
                    let ld = pb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let rd = pb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    (ld, rd)
                };
                let max_depth = _imax(new_left_depth, new_right_depth);

                {
                    let mut pb = parent.borrow_mut();
                    if pb.depth != max_depth {
                        pb.depth = max_depth;
                    } else {
                        // Depth didn't change at this level, stop bubbling
                        break;
                    }
                }

                // Check AVL property
                if new_left_depth == new_right_depth + 2 {
                    // Left is two deeper — rotate right
                    // Check left-right case first
                    let left_child = parent.borrow().left_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&left_child) > 0 {
                        _bostree_rotate_left(self, &left_child);
                    }
                    let rotated = _bostree_rotate_right(self, &parent);
                    bubble = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                } else if new_right_depth == new_left_depth + 2 {
                    // Right is two deeper — rotate left
                    // Check right-left case first
                    let right_child = parent.borrow().right_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&right_child) < 0 {
                        _bostree_rotate_right(self, &right_child);
                    }
                    let rotated = _bostree_rotate_left(self, &parent);
                    bubble = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                } else {
                    bubble = parent.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                }
            }
        }

        new_node
    }

    /// Remove a given node from the tree.
    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let bubble_up: Option<Rc<RefCell<BOSNode>>>;

        let has_left = node.borrow().left_child_node.is_some();
        let has_right = node.borrow().right_child_node.is_some();

        if has_left && has_right {
            // ── Case: node has two children ──────────────────────────────
            let candidate: Rc<RefCell<BOSNode>>;
            let bubble_start: Rc<RefCell<BOSNode>>;

            let left_depth = node.borrow().left_child_node.as_ref().unwrap().borrow().depth;
            let right_depth = node.borrow().right_child_node.as_ref().unwrap().borrow().depth;

            if left_depth >= right_depth {
                // Find rightmost node in left subtree (in-order predecessor)
                node.borrow_mut().left_child_count -= 1;
                let mut cand = node.borrow().left_child_node.as_ref().unwrap().clone();
                loop {
                    let has_right = cand.borrow().right_child_node.is_some();
                    if !has_right {
                        break;
                    }
                    cand.borrow_mut().right_child_count -= 1;
                    let next = cand.borrow().right_child_node.as_ref().unwrap().clone();
                    cand = next;
                }
                candidate = cand;
                let lost_child = candidate.borrow().left_child_node.clone();
                let bs = candidate.borrow().parent_node.as_ref()
                    .and_then(|w| w.upgrade())
                    .unwrap();

                // Replace candidate in its old position with lost_child
                {
                    let mut bs_b = bs.borrow_mut();
                    if bs_b.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate)) {
                        bs_b.left_child_node = lost_child.clone();
                    } else {
                        bs_b.right_child_node = lost_child.clone();
                    }
                }
                if let Some(ref lc) = lost_child {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&bs));
                }

                bubble_start = bs;
            } else {
                // Find leftmost node in right subtree (in-order successor)
                node.borrow_mut().right_child_count -= 1;
                let mut cand = node.borrow().right_child_node.as_ref().unwrap().clone();
                loop {
                    let has_left = cand.borrow().left_child_node.is_some();
                    if !has_left {
                        break;
                    }
                    cand.borrow_mut().left_child_count -= 1;
                    let next = cand.borrow().left_child_node.as_ref().unwrap().clone();
                    cand = next;
                }
                candidate = cand;
                let lost_child = candidate.borrow().right_child_node.clone();
                let bs = candidate.borrow().parent_node.as_ref()
                    .and_then(|w| w.upgrade())
                    .unwrap();

                // Replace candidate in its old position with lost_child
                {
                    let mut bs_b = bs.borrow_mut();
                    if bs_b.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate)) {
                        bs_b.left_child_node = lost_child.clone();
                    } else {
                        bs_b.right_child_node = lost_child.clone();
                    }
                }
                if let Some(ref lc) = lost_child {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&bs));
                }

                bubble_start = bs;
            }

            // Anchor candidate into node's position
            let node_parent = node.borrow().parent_node.clone();
            if let Some(ref pw) = node_parent {
                if let Some(parent) = pw.upgrade() {
                    let is_left = {
                        let pb = parent.borrow();
                        pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, node))
                    };
                    if is_left {
                        parent.borrow_mut().left_child_node = Some(candidate.clone());
                    } else {
                        parent.borrow_mut().right_child_node = Some(candidate.clone());
                    }
                }
            } else {
                self.root_node = Some(candidate.clone());
            }
            candidate.borrow_mut().parent_node = node_parent;

            // Move node's children to candidate
            let node_left = node.borrow().left_child_node.clone();
            let node_left_count = node.borrow().left_child_count;
            let node_right = node.borrow().right_child_node.clone();
            let node_right_count = node.borrow().right_child_count;

            candidate.borrow_mut().left_child_node = node_left.clone();
            candidate.borrow_mut().left_child_count = node_left_count;
            candidate.borrow_mut().right_child_node = node_right.clone();
            candidate.borrow_mut().right_child_count = node_right_count;

            if let Some(ref nl) = node_left {
                nl.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }
            if let Some(ref nr) = node_right {
                nr.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }

            // Rebalance from bubble_start up to (but not including) candidate
            let bubble_start_is_node = Rc::ptr_eq(&bubble_start, node);
            if !bubble_start_is_node {
                let mut cur: Option<Rc<RefCell<BOSNode>>> = Some(bubble_start.clone());
                loop {
                    let c = match cur {
                        Some(ref n) => n.clone(),
                        None => break,
                    };
                    if Rc::ptr_eq(&c, &candidate) {
                        break;
                    }
                    _recompute_depth(&c);
                    let balance = _bostree_balance(&c);
                    if balance > 1 {
                        // Rotate left, check right-left case
                        let rc = c.borrow().right_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&rc) < 0 {
                            _bostree_rotate_right(self, &rc);
                        }
                        let rotated = _bostree_rotate_left(self, &c);
                        cur = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    } else if balance < -1 {
                        // Rotate right, check left-right case
                        let lc = c.borrow().left_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&lc) > 0 {
                            _bostree_rotate_left(self, &lc);
                        }
                        let rotated = _bostree_rotate_right(self, &c);
                        cur = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    } else {
                        cur = c.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    }
                }
            }

            // Fix candidate's depth
            _recompute_depth(&candidate);

            // Bubble up from candidate's parent
            bubble_up = candidate.borrow().parent_node.as_ref()
                .and_then(|w| w.upgrade());

            // Decrement immediate parent's child count
            if let Some(ref bu) = bubble_up {
                let is_left = {
                    let bb = bu.borrow();
                    bb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate))
                };
                if is_left {
                    bu.borrow_mut().left_child_count -= 1;
                } else {
                    bu.borrow_mut().right_child_count -= 1;
                }
            }
        } else {
            // ── Case: node has at most one child ─────────────────────────
            let node_parent = node.borrow().parent_node.clone();

            if node_parent.is_none() {
                // Node is root
                let left = node.borrow().left_child_node.clone();
                let right = node.borrow().right_child_node.clone();
                if let Some(ref l) = left {
                    self.root_node = Some(l.clone());
                    l.borrow_mut().parent_node = None;
                } else if let Some(ref r) = right {
                    self.root_node = Some(r.clone());
                    r.borrow_mut().parent_node = None;
                } else {
                    self.root_node = None;
                }
                bubble_up = None;
            } else {
                let parent = node_parent.as_ref().unwrap().upgrade().unwrap();
                let candidate = if node.borrow().left_child_node.is_some() {
                    node.borrow().left_child_node.clone()
                } else {
                    node.borrow().right_child_node.clone()
                };
                let candidate_count = if node.borrow().left_child_node.is_some() {
                    node.borrow().left_child_count
                } else {
                    node.borrow().right_child_count
                };

                let is_left = {
                    let pb = parent.borrow();
                    pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, node))
                };

                if is_left {
                    parent.borrow_mut().left_child_node = candidate.clone();
                    parent.borrow_mut().left_child_count = candidate_count;
                } else {
                    parent.borrow_mut().right_child_node = candidate.clone();
                    parent.borrow_mut().right_child_count = candidate_count;
                }

                if let Some(ref c) = candidate {
                    c.borrow_mut().parent_node = Some(Rc::downgrade(&parent));
                }

                bubble_up = Some(parent);
            }
        }

        // Bubble up: decrement child counts and rebalance
        self._bubble_up_remove(bubble_up);

        // Mark node as invalid and unref
        node.borrow_mut().weak_ref_node_valid = 0;
        self.bostree_node_weak_unref(node);
    }

    /// Internal helper: bubble up after removal, decrementing counts and rebalancing.
    fn _bubble_up_remove(&mut self, mut bubble_up: Option<Rc<RefCell<BOSNode>>>) {
        let mut bubbling_finished = false;

        loop {
            let bu = match bubble_up {
                Some(ref n) => n.clone(),
                None => break,
            };

            if !bubbling_finished {
                let (left_depth, right_depth) = {
                    let bb = bu.borrow();
                    let ld = bb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let rd = bb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    (ld, rd)
                };
                let new_depth = _imax(left_depth, right_depth);
                let depth_changed = {
                    let bb = bu.borrow();
                    new_depth != bb.depth
                };
                bu.borrow_mut().depth = new_depth;

                let balance = _bostree_balance(&bu);
                if balance < -1 {
                    // Rotate right, check left-right case
                    let lc = bu.borrow().left_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&lc) > 0 {
                        _bostree_rotate_left(self, &lc);
                    }
                    let rotated = _bostree_rotate_right(self, &bu);
                    bubble_up = Self::_decrement_parent_count(&rotated);
                } else if balance > 1 {
                    // Rotate left, check right-left case
                    let rc = bu.borrow().right_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&rc) < 0 {
                        _bostree_rotate_right(self, &rc);
                    }
                    let rotated = _bostree_rotate_left(self, &bu);
                    bubble_up = Self::_decrement_parent_count(&rotated);
                } else {
                    if !depth_changed {
                        bubbling_finished = true;
                    }
                    bubble_up = Self::_decrement_parent_count(&bu);
                }
            } else {
                bubble_up = Self::_decrement_parent_count(&bu);
            }
        }
    }

    /// Decrement the appropriate child count of bu's parent, return parent.
    fn _decrement_parent_count(bu: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
        let parent = bu.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
        if let Some(ref p) = parent {
            let is_left = {
                let pb = p.borrow();
                pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, bu))
            };
            if is_left {
                p.borrow_mut().left_child_count -= 1;
            } else {
                p.borrow_mut().right_child_count -= 1;
            }
        }
        parent
    }

    /// Decrease the weak reference count for a node; if that was the last reference,
    /// free the node and return None; otherwise return the node.
    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        let count = {
            let mut nb = node.borrow_mut();
            nb.weak_ref_count -= 1;
            nb.weak_ref_count
        };
        if count == 0 {
            if let Some(free_fn) = self.free_function {
                free_fn(node);
            }
            None
        } else {
            let valid = node.borrow().weak_ref_node_valid;
            if valid != 0 {
                Some(node.clone())
            } else {
                None
            }
        }
    }

    /// Lookup a node in the tree by its key.
    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        loop {
            let node = match current {
                Some(ref n) => n.clone(),
                None => return None,
            };
            let cmp = (self.cmp_function)(key, &node.borrow().key);
            if cmp == 0 {
                return Some(node);
            } else if cmp < 0 {
                current = node.borrow().left_child_node.clone();
            } else {
                current = node.borrow().right_child_node.clone();
            }
        }
    }

    /// Return the node at the given in-order index (starting at 0).
    pub fn bostree_select(&self, index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        let mut idx = index;
        loop {
            let node = match current {
                Some(ref n) => n.clone(),
                None => return None,
            };
            let lcc = node.borrow().left_child_count;
            if lcc <= idx {
                idx -= lcc;
                if idx == 0 {
                    return Some(node);
                }
                idx -= 1;
                current = node.borrow().right_child_node.clone();
            } else {
                current = node.borrow().left_child_node.clone();
            }
        }
    }

    /// Print the tree (only available in debug builds).
    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        if let Some(ref root) = self.root_node {
            println!("digraph {{\n  ordering = out;");
            Self::_print_helper(root);
            println!("}}");
        }
    }

    #[cfg(debug_assertions)]
    fn _print_helper(node: &Rc<RefCell<BOSNode>>) {
        let key = node.borrow().key.clone();
        let lcc = node.borrow().left_child_count;
        let rcc = node.borrow().right_child_count;
        let d = node.borrow().depth;
        println!(
            "  {} [label=\"\\N ({},{},{})\"];",
            key, lcc, rcc, d
        );
        let parent_key = {
            let nb = node.borrow();
            nb.parent_node.as_ref().and_then(|pw| pw.upgrade()).map(|p| p.borrow().key.clone())
        };
        if let Some(ref pk) = parent_key {
            println!("  {} -> {} [color=green];", key, pk);
        }
        let left = node.borrow().left_child_node.clone();
        if let Some(ref l) = left {
            println!("  {} -> {}", key, l.borrow().key);
            Self::_print_helper(l);
        }
        let right = node.borrow().right_child_node.clone();
        if let Some(ref r) = right {
            println!("  {} -> {}", key, r.borrow().key);
            Self::_print_helper(r);
        }
    }
}

/// Increase the weak reference count for a node and return the node.
pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let mut nb = node.borrow_mut();
    assert!(nb.weak_ref_count < 127);
    assert!(nb.weak_ref_count > 0);
    nb.weak_ref_count += 1;
    node.clone()
}

/// Return the next node in an in-order traversal.
pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if node.borrow().right_child_node.is_some() {
        let mut current = node.borrow().right_child_node.clone().unwrap();
        loop {
            let has_left = current.borrow().left_child_node.is_some();
            if !has_left {
                break;
            }
            let next = current.borrow().left_child_node.clone().unwrap();
            current = next;
        }
        Some(current)
    } else if node.borrow().parent_node.is_some() {
        let mut current = node.clone();
        loop {
            let parent = current.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            let is_right_child = match &parent {
                Some(p) => {
                    let pb = p.borrow();
                    pb.right_child_node.as_ref().map_or(false, |rc| Rc::ptr_eq(rc, &current))
                }
                None => false,
            };
            if is_right_child {
                current = parent.unwrap();
            } else {
                return parent;
            }
        }
    } else {
        None
    }
}

/// Return the previous node in an in-order traversal.
pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if node.borrow().left_child_node.is_some() {
        let mut current = node.borrow().left_child_node.clone().unwrap();
        loop {
            let has_right = current.borrow().right_child_node.is_some();
            if !has_right {
                break;
            }
            let next = current.borrow().right_child_node.clone().unwrap();
            current = next;
        }
        Some(current)
    } else if node.borrow().parent_node.is_some() {
        let mut current = node.clone();
        loop {
            let parent = current.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            let is_left_child = match &parent {
                Some(p) => {
                    let pb = p.borrow();
                    pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &current))
                }
                None => false,
            };
            if is_left_child {
                current = parent.unwrap();
            } else {
                return parent;
            }
        }
    } else {
        None
    }
}

/// Return the rank (in-order index) of the given node.
pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut current = node.clone();
    loop {
        let parent_weak = current.borrow().parent_node.clone();
        let parent = match parent_weak {
            Some(ref w) => match w.upgrade() {
                Some(p) => p,
                None => break,
            },
            None => break,
        };
        let is_right = {
            let pb = parent.borrow();
            pb.right_child_node.as_ref().map_or(false, |rc| Rc::ptr_eq(rc, &current))
        };
        if is_right {
            counter += 1 + parent.borrow().left_child_count;
        }
        current = parent;
    }
    counter
}

use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct BOSTree {
    /// The root node of the tree.
    pub root_node: Option<Rc<RefCell<BOSNode>>>,
    /// The key comparison function.
    pub cmp_function: BOSTreeCmpFunction,
    /// The optional free function for node data.
    pub free_function: Option<BOSTreeFreeFunction>,
}

/// The node structure.
#[derive(Debug)]
pub struct BOSNode {
    /// Number of nodes in the left subtree.
    pub left_child_count: u32,
    /// Number of nodes in the right subtree.
    pub right_child_count: u32,
    /// Cached depth of the node.
    pub depth: u32,
    /// Left child node.
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    /// Right child node.
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    /// Parent node (using a weak reference to avoid cycles).
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    /// The key for this node.
    pub key: String,
    /// The associated data.
    pub data: Option<String>,
    /// Internal weak reference counter.
    pub weak_ref_count: u8,
    /// Validity flag for the weak reference.
    pub weak_ref_node_valid: u8,
}

/// Type alias for a key comparison function.
pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;

/// Type alias for a free function which will be called on nodes
/// that are removed.
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

// ─── Private helper functions ───────────────────────────────────────────────

#[inline]
fn _imax(i1: u32, i2: u32) -> u32 {
    if i1 > i2 { i1 } else { i2 }
}

/// Returns right_depth - left_depth for the given node.
#[inline]
fn _bostree_balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
    let b = node.borrow();
    let left_depth = b.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
    let right_depth = b.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
    (right_depth as i32) - (left_depth as i32)
}

/// Recompute and store the depth field of a node from its children.
#[inline]
fn _recompute_depth(node: &Rc<RefCell<BOSNode>>) {
    let (ld, rd) = {
        let b = node.borrow();
        let ld = b.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let rd = b.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        (ld, rd)
    };
    node.borrow_mut().depth = _imax(ld, rd);
}

/// Rotate right around node P.
fn _bostree_rotate_right(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let l = p.borrow().left_child_node.as_ref().unwrap().clone();
    let p_parent = p.borrow().parent_node.clone();

    // Update grandparent to point to L instead of P
    if let Some(ref pw) = p_parent {
        if let Some(parent) = pw.upgrade() {
            let is_left = {
                let pb = parent.borrow();
                pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, p))
            };
            if is_left {
                parent.borrow_mut().left_child_node = Some(l.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(l.clone());
            }
        }
    } else {
        tree.root_node = Some(l.clone());
    }

    l.borrow_mut().parent_node = p_parent;

    let l_right = l.borrow().right_child_node.clone();
    let l_right_count = l.borrow().right_child_count;

    p.borrow_mut().left_child_node = l_right.clone();
    p.borrow_mut().left_child_count = l_right_count;

    if let Some(ref lr) = l_right {
        lr.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    _recompute_depth(p);
    p.borrow_mut().parent_node = Some(Rc::downgrade(&l));
    l.borrow_mut().right_child_node = Some(p.clone());
    l.borrow_mut().right_child_count =
        p.borrow().left_child_count + p.borrow().right_child_count + 1;
    _recompute_depth(&l);

    l
}

/// Rotate left around node P.
fn _bostree_rotate_left(tree: &mut BOSTree, p: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let r = p.borrow().right_child_node.as_ref().unwrap().clone();
    let p_parent = p.borrow().parent_node.clone();

    if let Some(ref pw) = p_parent {
        if let Some(parent) = pw.upgrade() {
            let is_left = {
                let pb = parent.borrow();
                pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, p))
            };
            if is_left {
                parent.borrow_mut().left_child_node = Some(r.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(r.clone());
            }
        }
    } else {
        tree.root_node = Some(r.clone());
    }

    r.borrow_mut().parent_node = p_parent;

    let r_left = r.borrow().left_child_node.clone();
    let r_left_count = r.borrow().left_child_count;

    p.borrow_mut().right_child_node = r_left.clone();
    p.borrow_mut().right_child_count = r_left_count;

    if let Some(ref rl) = r_left {
        rl.borrow_mut().parent_node = Some(Rc::downgrade(p));
    }

    _recompute_depth(p);
    p.borrow_mut().parent_node = Some(Rc::downgrade(&r));
    r.borrow_mut().left_child_node = Some(p.clone());
    r.borrow_mut().left_child_count =
        p.borrow().left_child_count + p.borrow().right_child_count + 1;
    _recompute_depth(&r);

    r
}

// ─── Public API ─────────────────────────────────────────────────────────────

impl BOSTree {
    /// Create a new tree with a mandatory comparison function and an optional free function.
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    /// Return the number of nodes in the tree.
    pub fn bostree_node_count(&self) -> u32 {
        self.root_node.as_ref().map_or(0, |n| {
            let b = n.borrow();
            b.left_child_count + b.right_child_count + 1
        })
    }

    /// Insert a new member into the tree and return the associated node.
    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        let mut current = self.root_node.clone();
        let mut parent_node: Option<Rc<RefCell<BOSNode>>> = None;

        while let Some(node) = current {
            parent_node = Some(node.clone());
            let cmp = (self.cmp_function)(&key, &node.borrow().key);
            if cmp < 0 {
                node.borrow_mut().left_child_count += 1;
                current = node.borrow().left_child_node.clone();
            } else {
                node.borrow_mut().right_child_count += 1;
                current = node.borrow().right_child_node.clone();
            }
        }

        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: parent_node.as_ref().map(|p| Rc::downgrade(p)),
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        if let Some(ref parent) = parent_node {
            let cmp = (self.cmp_function)(
                &new_node.borrow().key,
                &parent.borrow().key,
            );
            if cmp < 0 {
                parent.borrow_mut().left_child_node = Some(new_node.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(new_node.clone());
            }
        } else {
            self.root_node = Some(new_node.clone());
            return new_node;
        }

        let should_bubble = {
            let pb = parent_node.as_ref().unwrap().borrow();
            pb.left_child_node.is_some() ^ pb.right_child_node.is_some()
        };

        if should_bubble {
            parent_node.as_ref().unwrap().borrow_mut().depth = 1;

            let mut bubble: Option<Rc<RefCell<BOSNode>>> =
                parent_node.as_ref().unwrap().borrow().parent_node.as_ref()
                    .and_then(|w| w.upgrade());

            while let Some(parent) = bubble {
                let (new_left_depth, new_right_depth) = {
                    let pb = parent.borrow();
                    let ld = pb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let rd = pb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    (ld, rd)
                };
                let max_depth = _imax(new_left_depth, new_right_depth);

                {
                    let mut pb = parent.borrow_mut();
                    if pb.depth != max_depth {
                        pb.depth = max_depth;
                    } else {
                        break;
                    }
                }

                if new_left_depth == new_right_depth + 2 {
                    let left_child = parent.borrow().left_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&left_child) > 0 {
                        _bostree_rotate_left(self, &left_child);
                    }
                    let rotated = _bostree_rotate_right(self, &parent);
                    bubble = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                } else if new_right_depth == new_left_depth + 2 {
                    let right_child = parent.borrow().right_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&right_child) < 0 {
                        _bostree_rotate_right(self, &right_child);
                    }
                    let rotated = _bostree_rotate_left(self, &parent);
                    bubble = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                } else {
                    bubble = parent.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                }
            }
        }

        new_node
    }

    /// Remove a given node from the tree.
    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let bubble_up: Option<Rc<RefCell<BOSNode>>>;

        let has_left = node.borrow().left_child_node.is_some();
        let has_right = node.borrow().right_child_node.is_some();

        if has_left && has_right {
            let candidate: Rc<RefCell<BOSNode>>;
            let bubble_start: Rc<RefCell<BOSNode>>;

            let left_depth = node.borrow().left_child_node.as_ref().unwrap().borrow().depth;
            let right_depth = node.borrow().right_child_node.as_ref().unwrap().borrow().depth;

            if left_depth >= right_depth {
                node.borrow_mut().left_child_count -= 1;
                let mut cand = node.borrow().left_child_node.as_ref().unwrap().clone();
                while cand.borrow().right_child_node.is_some() {
                    cand.borrow_mut().right_child_count -= 1;
                    let next = cand.borrow().right_child_node.as_ref().unwrap().clone();
                    cand = next;
                }
                candidate = cand;
                let lost_child = candidate.borrow().left_child_node.clone();
                let bs = candidate.borrow().parent_node.as_ref()
                    .and_then(|w| w.upgrade()).unwrap();

                {
                    let mut bs_b = bs.borrow_mut();
                    if bs_b.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate)) {
                        bs_b.left_child_node = lost_child.clone();
                    } else {
                        bs_b.right_child_node = lost_child.clone();
                    }
                }
                if let Some(ref lc) = lost_child {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&bs));
                }
                bubble_start = bs;
            } else {
                node.borrow_mut().right_child_count -= 1;
                let mut cand = node.borrow().right_child_node.as_ref().unwrap().clone();
                while cand.borrow().left_child_node.is_some() {
                    cand.borrow_mut().left_child_count -= 1;
                    let next = cand.borrow().left_child_node.as_ref().unwrap().clone();
                    cand = next;
                }
                candidate = cand;
                let lost_child = candidate.borrow().right_child_node.clone();
                let bs = candidate.borrow().parent_node.as_ref()
                    .and_then(|w| w.upgrade()).unwrap();

                {
                    let mut bs_b = bs.borrow_mut();
                    if bs_b.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate)) {
                        bs_b.left_child_node = lost_child.clone();
                    } else {
                        bs_b.right_child_node = lost_child.clone();
                    }
                }
                if let Some(ref lc) = lost_child {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&bs));
                }
                bubble_start = bs;
            }

            let node_parent = node.borrow().parent_node.clone();
            if let Some(ref pw) = node_parent {
                if let Some(parent) = pw.upgrade() {
                    let is_left = {
                        let pb = parent.borrow();
                        pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, node))
                    };
                    if is_left {
                        parent.borrow_mut().left_child_node = Some(candidate.clone());
                    } else {
                        parent.borrow_mut().right_child_node = Some(candidate.clone());
                    }
                }
            } else {
                self.root_node = Some(candidate.clone());
            }
            candidate.borrow_mut().parent_node = node_parent;

            let node_left = node.borrow().left_child_node.clone();
            let node_left_count = node.borrow().left_child_count;
            let node_right = node.borrow().right_child_node.clone();
            let node_right_count = node.borrow().right_child_count;

            candidate.borrow_mut().left_child_node = node_left.clone();
            candidate.borrow_mut().left_child_count = node_left_count;
            candidate.borrow_mut().right_child_node = node_right.clone();
            candidate.borrow_mut().right_child_count = node_right_count;

            if let Some(ref nl) = node_left {
                nl.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }
            if let Some(ref nr) = node_right {
                nr.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }

            let bubble_start_is_node = Rc::ptr_eq(&bubble_start, node);
            if !bubble_start_is_node {
                let mut cur: Option<Rc<RefCell<BOSNode>>> = Some(bubble_start.clone());
                while let Some(c) = cur {
                    if Rc::ptr_eq(&c, &candidate) { break; }
                    _recompute_depth(&c);
                    let balance = _bostree_balance(&c);
                    if balance > 1 {
                        let rc = c.borrow().right_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&rc) < 0 {
                            _bostree_rotate_right(self, &rc);
                        }
                        let rotated = _bostree_rotate_left(self, &c);
                        cur = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    } else if balance < -1 {
                        let lc = c.borrow().left_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&lc) > 0 {
                            _bostree_rotate_left(self, &lc);
                        }
                        let rotated = _bostree_rotate_right(self, &c);
                        cur = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    } else {
                        cur = c.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    }
                }
            }

            _recompute_depth(&candidate);
            bubble_up = candidate.borrow().parent_node.as_ref().and_then(|w| w.upgrade());

            if let Some(ref bu) = bubble_up {
                let is_left = {
                    let bb = bu.borrow();
                    bb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &candidate))
                };
                if is_left {
                    bu.borrow_mut().left_child_count -= 1;
                } else {
                    bu.borrow_mut().right_child_count -= 1;
                }
            }
        } else {
            let node_parent = node.borrow().parent_node.clone();

            if node_parent.is_none() {
                let left = node.borrow().left_child_node.clone();
                let right = node.borrow().right_child_node.clone();
                if let Some(ref l) = left {
                    self.root_node = Some(l.clone());
                    l.borrow_mut().parent_node = None;
                } else if let Some(ref r) = right {
                    self.root_node = Some(r.clone());
                    r.borrow_mut().parent_node = None;
                } else {
                    self.root_node = None;
                }
                bubble_up = None;
            } else {
                let parent = node_parent.as_ref().unwrap().upgrade().unwrap();
                let (candidate, candidate_count) = {
                    let nb = node.borrow();
                    if nb.left_child_node.is_some() {
                        (nb.left_child_node.clone(), nb.left_child_count)
                    } else {
                        (nb.right_child_node.clone(), nb.right_child_count)
                    }
                };

                let is_left = {
                    let pb = parent.borrow();
                    pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, node))
                };

                if is_left {
                    parent.borrow_mut().left_child_node = candidate.clone();
                    parent.borrow_mut().left_child_count = candidate_count;
                } else {
                    parent.borrow_mut().right_child_node = candidate.clone();
                    parent.borrow_mut().right_child_count = candidate_count;
                }

                if let Some(ref c) = candidate {
                    c.borrow_mut().parent_node = Some(Rc::downgrade(&parent));
                }

                bubble_up = Some(parent);
            }
        }

        self._bubble_up_remove(bubble_up);
        node.borrow_mut().weak_ref_node_valid = 0;
        self.bostree_node_weak_unref(node);
    }

    fn _bubble_up_remove(&mut self, mut bubble_up: Option<Rc<RefCell<BOSNode>>>) {
        let mut bubbling_finished = false;

        while let Some(bu) = bubble_up {
            if !bubbling_finished {
                let (left_depth, right_depth) = {
                    let bb = bu.borrow();
                    let ld = bb.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let rd = bb.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    (ld, rd)
                };
                let new_depth = _imax(left_depth, right_depth);
                let depth_changed = {
                    let bb = bu.borrow();
                    new_depth != bb.depth
                };
                bu.borrow_mut().depth = new_depth;

                let balance = _bostree_balance(&bu);
                if balance < -1 {
                    let lc = bu.borrow().left_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&lc) > 0 {
                        _bostree_rotate_left(self, &lc);
                    }
                    let rotated = _bostree_rotate_right(self, &bu);
                    bubble_up = Self::_decrement_parent_count(&rotated);
                } else if balance > 1 {
                    let rc = bu.borrow().right_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&rc) < 0 {
                        _bostree_rotate_right(self, &rc);
                    }
                    let rotated = _bostree_rotate_left(self, &bu);
                    bubble_up = Self::_decrement_parent_count(&rotated);
                } else {
                    if !depth_changed {
                        bubbling_finished = true;
                    }
                    bubble_up = Self::_decrement_parent_count(&bu);
                }
            } else {
                bubble_up = Self::_decrement_parent_count(&bu);
            }
        }
    }

    fn _decrement_parent_count(bu: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
        let parent = bu.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
        if let Some(ref p) = parent {
            let is_left = {
                let pb = p.borrow();
                pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, bu))
            };
            if is_left {
                p.borrow_mut().left_child_count -= 1;
            } else {
                p.borrow_mut().right_child_count -= 1;
            }
        }
        parent
    }

    /// Decrease the weak reference count for a node.
    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        let count = {
            let mut nb = node.borrow_mut();
            nb.weak_ref_count -= 1;
            nb.weak_ref_count
        };
        if count == 0 {
            if let Some(free_fn) = self.free_function {
                free_fn(node);
            }
            None
        } else {
            let valid = node.borrow().weak_ref_node_valid;
            if valid != 0 { Some(node.clone()) } else { None }
        }
    }

    /// Lookup a node in the tree by its key.
    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        while let Some(node) = current {
            let (node_key_cmp, left, right) = {
                let b = node.borrow();
                ((self.cmp_function)(key, &b.key), b.left_child_node.clone(), b.right_child_node.clone())
            };
            if node_key_cmp == 0 {
                return Some(node);
            } else if node_key_cmp < 0 {
                current = left;
            } else {
                current = right;
            }
        }
        None
    }

    /// Return the node at the given in-order index (starting at 0).
    pub fn bostree_select(&self, index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        let mut idx = index;
        while let Some(node) = current {
            let (lcc, left, right) = {
                let b = node.borrow();
                (b.left_child_count, b.left_child_node.clone(), b.right_child_node.clone())
            };
            if lcc <= idx {
                idx -= lcc;
                if idx == 0 {
                    return Some(node);
                }
                idx -= 1;
                current = right;
            } else {
                current = left;
            }
        }
        None
    }

    /// Print the tree (only available in debug builds).
    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        if let Some(ref root) = self.root_node {
            println!("digraph {{\n  ordering = out;");
            Self::_print_helper(root);
            println!("}}");
        }
    }

    #[cfg(debug_assertions)]
    fn _print_helper(node: &Rc<RefCell<BOSNode>>) {
        let (key, lcc, rcc, d, parent_key, left, right) = {
            let nb = node.borrow();
            (
                nb.key.clone(),
                nb.left_child_count,
                nb.right_child_count,
                nb.depth,
                nb.parent_node.as_ref().and_then(|pw| pw.upgrade()).map(|p| p.borrow().key.clone()),
                nb.left_child_node.clone(),
                nb.right_child_node.clone(),
            )
        };
        println!("  {} [label=\"\\N ({},{},{})\"];", key, lcc, rcc, d);
        if let Some(ref pk) = parent_key {
            println!("  {} -> {} [color=green];", key, pk);
        }
        if let Some(ref l) = left {
            println!("  {} -> {}", key, l.borrow().key);
            Self::_print_helper(l);
        }
        if let Some(ref r) = right {
            println!("  {} -> {}", key, r.borrow().key);
            Self::_print_helper(r);
        }
    }
}

/// Increase the weak reference count for a node and return the node.
pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let mut nb = node.borrow_mut();
    assert!(nb.weak_ref_count < 127);
    assert!(nb.weak_ref_count > 0);
    nb.weak_ref_count += 1;
    node.clone()
}

/// Return the next node in an in-order traversal.
pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if node.borrow().right_child_node.is_some() {
        let mut current = node.borrow().right_child_node.clone().unwrap();
        while current.borrow().left_child_node.is_some() {
            let next = current.borrow().left_child_node.clone().unwrap();
            current = next;
        }
        Some(current)
    } else if node.borrow().parent_node.is_some() {
        let mut current = node.clone();
        loop {
            let parent = current.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            let is_right_child = match &parent {
                Some(p) => {
                    let pb = p.borrow();
                    pb.right_child_node.as_ref().map_or(false, |rc| Rc::ptr_eq(rc, &current))
                }
                None => false,
            };
            if is_right_child {
                current = parent.unwrap();
            } else {
                return parent;
            }
        }
    } else {
        None
    }
}

/// Return the previous node in an in-order traversal.
pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if node.borrow().left_child_node.is_some() {
        let mut current = node.borrow().left_child_node.clone().unwrap();
        while current.borrow().right_child_node.is_some() {
            let next = current.borrow().right_child_node.clone().unwrap();
            current = next;
        }
        Some(current)
    } else if node.borrow().parent_node.is_some() {
        let mut current = node.clone();
        loop {
            let parent = current.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            let is_left_child = match &parent {
                Some(p) => {
                    let pb = p.borrow();
                    pb.left_child_node.as_ref().map_or(false, |lc| Rc::ptr_eq(lc, &current))
                }
                None => false,
            };
            if is_left_child {
                current = parent.unwrap();
            } else {
                return parent;
            }
        }
    } else {
        None
    }
}

/// Return the rank (in-order index) of the given node.
pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut current = node.clone();
    loop {
        let parent = match current.borrow().parent_node.clone() {
            Some(ref w) => match w.upgrade() {
                Some(p) => p,
                None => break,
            },
            None => break,
        };
        let is_right = {
            let pb = parent.borrow();
            pb.right_child_node.as_ref().map_or(false, |rc| Rc::ptr_eq(rc, &current))
        };
        if is_right {
            counter += 1 + parent.borrow().left_child_count;
        }
        current = parent;
    }
    counter
}
